<?php require_once __DIR__.'/../config/db.php';require_once __DIR__.'/../services/userService.php';require_once __DIR__.'/../includes/auth.php';if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit('POST required');}$pdo=openDatabase();$admin=requireLogin($pdo);requireRole($admin,['Administrator']);verifyCsrfToken($_POST);$id=filter_input(INPUT_POST,'user_id',FILTER_VALIDATE_INT);try{removeManagedUser($pdo,$id);header('Location: manage-users.php?deleted=1',true,303);exit;}catch(Throwable $e){http_response_code(422);exit(htmlspecialchars($e->getMessage(),ENT_QUOTES,'UTF-8'));}
